{"content": "//! Encrypted storage + application state for ROVault.
//!
//! On-disk layout (in the OS app-config dir, e.g. %APPDATA%\ROVault\):
//!   vault.json  -> { name, keyfile, entries_blob }
//!
//! `keyfile` is safe metadata (salts, wrapped DEKs, verifier).
//! `entries_blob` is the full credential list, serialized to JSON then
//! encrypted with the DEK via XChaCha20-Poly1305. Nothing readable ever
//! touches the disk. Plaintext entries live only in memory while unlocked.

use crate::crypto::{self, KeyFile, KdfParams, SecretKey};
use serde::{Deserialize, Serialize};
use std::path::PathBuf;
use std::sync::Mutex;
use uuid::Uuid;

pub const VAULT_FILE: &str = "vault.json";

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct Credential {
    pub id: String,
    pub provider: String,
    pub username: String,
    pub password: String,
    #[serde(default)]
    pub url: String,
    #[serde(default)]
    pub category: String,
    #[serde(default)]
    pub notes: String,
    #[serde(default)]
    pub favorite: bool,
    #[serde(default)]
    pub created_at: i64,
    #[serde(default)]
    pub updated_at: i64,
}

/// The plaintext contents of a vault, held in memory only while unlocked.
#[derive(Debug, Clone, Default, Serialize, Deserialize)]
pub struct VaultData {
    pub entries: Vec<Credential>,
}

/// What lands on disk.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct VaultFile {
    pub name: String,
    pub version: u32,
    pub keyfile: KeyFile,
    /// Encrypted VaultData (JSON) — ciphertext only.
    pub entries_blob: Vec<u8>,
}

/// In-memory runtime state guarded by a Mutex behind Tauri's managed state.
#[derive(Default)]
pub struct SessionInner {
    pub unlocked: bool,
    pub dek: Option<SecretKey>,
    pub name: String,
    pub keyfile: Option<KeyFile>,
    pub data: VaultData,
}

pub struct AppState {
    pub session: Mutex<SessionInner>,
    pub vault_path: Mutex<Option<PathBuf>>,
}

impl Default for AppState {
    fn default() -> Self {
        AppState {
            session: Mutex::new(SessionInner::default()),
            vault_path: Mutex::new(None),
        }
    }
}

#[derive(Debug)]
pub enum StoreError {
    Crypto(crypto::CryptoError),
    Io(String),
    Serde(String),
    Locked,
    NotFound,
}

impl std::fmt::Display for StoreError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            StoreError::Crypto(e) => write!(f, "{e}"),
            StoreError::Io(e) => write!(f, "storage error: {e}"),
            StoreError::Serde(e) => write!(f, "data error: {e}"),
            StoreError::Locked => write!(f, "vault is locked"),
            StoreError::NotFound => write!(f, "no vault found"),
        }
    }
}
impl std::error::Error for StoreError {}

impl From<crypto::CryptoError> for StoreError {
    fn from(e: crypto::CryptoError) -> Self {
        StoreError::Crypto(e)
    }
}

/// Encrypt VaultData -> ciphertext blob.
pub fn seal_data(dek: &SecretKey, data: &VaultData) -> Result<Vec<u8>, StoreError> {
    let json = serde_json::to_vec(data).map_err(|e| StoreError::Serde(e.to_string()))?;
    Ok(crypto::encrypt_payload(dek, &json)?)
}

/// Decrypt ciphertext blob -> VaultData.
pub fn open_data(dek: &SecretKey, blob: &[u8]) -> Result<VaultData, StoreError> {
    if blob.is_empty() {
        return Ok(VaultData::default());
    }
    let json = crypto::decrypt_payload(dek, blob)?;
    serde_json::from_slice(&json).map_err(|e| StoreError::Serde(e.to_string()))
}

pub fn read_vault_file(path: &PathBuf) -> Result<VaultFile, StoreError> {
    let bytes = std::fs::read(path).map_err(|e| StoreError::Io(e.to_string()))?;
    serde_json::from_slice(&bytes).map_err(|e| StoreError::Serde(e.to_string()))
}

pub fn write_vault_file(path: &PathBuf, vf: &VaultFile) -> Result<(), StoreError> {
    if let Some(parent) = path.parent() {
        std::fs::create_dir_all(parent).map_err(|e| StoreError::Io(e.to_string()))?;
    }
    let bytes = serde_json::to_vec_pretty(vf).map_err(|e| StoreError::Serde(e.to_string()))?;
    // Atomic-ish write: temp then rename.
    let tmp = path.with_extension("json.tmp");
    std::fs::write(&tmp, &bytes).map_err(|e| StoreError::Io(e.to_string()))?;
    std::fs::rename(&tmp, path).map_err(|e| StoreError::Io(e.to_string()))?;
    Ok(())
}

pub fn now_secs() -> i64 {
    std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .map(|d| d.as_secs() as i64)
        .unwrap_or(0)
}

pub fn new_id() -> String {
    Uuid::new_v4().to_string()
}

pub fn default_kdf() -> KdfParams {
    KdfParams::default()
}
