{"content": "mod crypto;
mod store;

use serde::{Deserialize, Serialize};
use std::path::PathBuf;
use store::{AppState, Credential, StoreError, VaultData, VaultFile};
use tauri::{Manager, State};

// ---- helpers ----

fn err<E: std::fmt::Display>(e: E) -> String {
    e.to_string()
}

fn vault_path(app: &tauri::AppHandle) -> Result<PathBuf, String> {
    let dir = app
        .path()
        .app_config_dir()
        .map_err(|e| format!("cannot resolve config dir: {e}"))?;
    Ok(dir.join("ROVault").join(store::VAULT_FILE))
}

/// Persist current in-memory data (re-encrypting) back to disk.
fn persist(state: &State<AppState>) -> Result<(), String> {
    let session = state.session.lock().unwrap();
    if !session.unlocked {
        return Err(StoreError::Locked.to_string());
    }
    let dek = session.dek.as_ref().ok_or(StoreError::Locked).map_err(err)?;
    let keyfile = session.keyfile.as_ref().ok_or(StoreError::Locked).map_err(err)?;
    let blob = store::seal_data(dek, &session.data).map_err(err)?;
    let vf = VaultFile {
        name: session.name.clone(),
        version: 1,
        keyfile: keyfile.clone(),
        entries_blob: blob,
    };
    let path_guard = state.vault_path.lock().unwrap();
    let path = path_guard.as_ref().ok_or(StoreError::NotFound).map_err(err)?;
    store::write_vault_file(path, &vf).map_err(err)
}

// ---- DTOs ----

#[derive(Serialize)]
pub struct VaultStatus {
    pub exists: bool,
    pub unlocked: bool,
    pub name: String,
}

#[derive(Serialize)]
pub struct ProvisionResult {
    pub recovery_key: String,
}

// ---- commands ----

#[tauri::command]
fn get_status(app: tauri::AppHandle, state: State<AppState>) -> Result<VaultStatus, String> {
    let path = vault_path(&app)?;
    let exists = path.exists();
    // cache the path
    *state.vault_path.lock().unwrap() = Some(path);
    let session = state.session.lock().unwrap();
    Ok(VaultStatus {
        exists,
        unlocked: session.unlocked,
        name: session.name.clone(),
    })
}

/// First-launch onboarding: create the vault. Returns the recovery key ONCE.
#[tauri::command]
fn create_vault(
    app: tauri::AppHandle,
    state: State<AppState>,
    name: String,
    password: String,
) -> Result<ProvisionResult, String> {
    let path = vault_path(&app)?;
    if path.exists() {
        return Err("a vault already exists".into());
    }
    let provisioned = crypto::provision(&password, store::default_kdf()).map_err(err)?;
    let data = VaultData::default();
    let blob = store::seal_data(&provisioned.dek, &data).map_err(err)?;
    let vf = VaultFile {
        name: name.clone(),
        version: 1,
        keyfile: provisioned.keyfile.clone(),
        entries_blob: blob,
    };
    store::write_vault_file(&path, &vf).map_err(err)?;

    // Auto-unlock into the new session.
    {
        let mut session = state.session.lock().unwrap();
        session.unlocked = true;
        session.dek = Some(provisioned.dek);
        session.name = name;
        session.keyfile = Some(provisioned.keyfile);
        session.data = data;
    }
    *state.vault_path.lock().unwrap() = Some(path);

    Ok(ProvisionResult {
        recovery_key: provisioned.recovery_key,
    })
}

#[tauri::command]
fn unlock(
    app: tauri::AppHandle,
    state: State<AppState>,
    secret: String,
    use_recovery: bool,
) -> Result<VaultStatus, String> {
    let path = vault_path(&app)?;
    let vf = store::read_vault_file(&path).map_err(err)?;
    let dek = if use_recovery {
        crypto::unlock_with_recovery(&vf.keyfile, &secret).map_err(err)?
    } else {
        crypto::unlock_with_password(&vf.keyfile, &secret).map_err(err)?
    };
    let data = store::open_data(&dek, &vf.entries_blob).map_err(err)?;

    let mut session = state.session.lock().unwrap();
    session.unlocked = true;
    session.dek = Some(dek);
    session.name = vf.name.clone();
    session.keyfile = Some(vf.keyfile);
    session.data = data;
    *state.vault_path.lock().unwrap() = Some(path);

    Ok(VaultStatus {
        exists: true,
        unlocked: true,
        name: vf.name,
    })
}

/// Lock the vault: wipe the DEK and plaintext from memory.
#[tauri::command]
fn lock(state: State<AppState>) -> Result<(), String> {
    let mut session = state.session.lock().unwrap();
    session.unlocked = false;
    session.dek = None; // SecretKey zeroizes on drop
    session.data = VaultData::default();
    Ok(())
}

#[tauri::command]
fn list_entries(state: State<AppState>) -> Result<Vec<Credential>, String> {
    let session = state.session.lock().unwrap();
    if !session.unlocked {
        return Err(StoreError::Locked.to_string());
    }
    Ok(session.data.entries.clone())
}

#[tauri::command]
fn upsert_entry(state: State<AppState>, mut entry: Credential) -> Result<Credential, String> {
    {
        let mut session = state.session.lock().unwrap();
        if !session.unlocked {
            return Err(StoreError::Locked.to_string());
        }
        let now = store::now_secs();
        if entry.id.is_empty() {
            entry.id = store::new_id();
            entry.created_at = now;
            entry.updated_at = now;
            session.data.entries.push(entry.clone());
        } else {
            entry.updated_at = now;
            if let Some(existing) = session.data.entries.iter_mut().find(|e| e.id == entry.id) {
                entry.created_at = existing.created_at;
                *existing = entry.clone();
            } else {
                return Err(StoreError::NotFound.to_string());
            }
        }
    }
    persist(&state)?;
    Ok(entry)
}

#[tauri::command]
fn delete_entry(state: State<AppState>, id: String) -> Result<(), String> {
    {
        let mut session = state.session.lock().unwrap();
        if !session.unlocked {
            return Err(StoreError::Locked.to_string());
        }
        let before = session.data.entries.len();
        session.data.entries.retain(|e| e.id != id);
        if session.data.entries.len() == before {
            return Err(StoreError::NotFound.to_string());
        }
    }
    persist(&state)
}

#[tauri::command]
fn change_master_password(
    state: State<AppState>,
    current_password: String,
    new_password: String,
) -> Result<(), String> {
    {
        let mut session = state.session.lock().unwrap();
        if !session.unlocked {
            return Err(StoreError::Locked.to_string());
        }
        let keyfile = session.keyfile.clone().ok_or(StoreError::Locked).map_err(err)?;
        // Verify the current password first.
        crypto::unlock_with_password(&keyfile, &current_password).map_err(err)?;
        let dek = session.dek.as_ref().ok_or(StoreError::Locked).map_err(err)?;
        let updated = crypto::change_password(&keyfile, dek, &new_password).map_err(err)?;
        session.keyfile = Some(updated);
    }
    persist(&state)
}

// ---- import / export ----

#[derive(Serialize, Deserialize)]
pub struct PlainExport {
    pub name: String,
    pub exported_at: i64,
    pub entries: Vec<Credential>,
}

/// Encrypted backup: returns the raw VaultFile JSON (already ciphertext for entries).
#[tauri::command]
fn export_encrypted(app: tauri::AppHandle, state: State<AppState>) -> Result<String, String> {
    let session = state.session.lock().unwrap();
    if !session.unlocked {
        return Err(StoreError::Locked.to_string());
    }
    drop(session);
    let path = vault_path(&app)?;
    let vf = store::read_vault_file(&path).map_err(err)?;
    serde_json::to_string_pretty(&vf).map_err(err)
}

/// Plaintext export — caller must re-confirm password at the UI layer.
#[tauri::command]
fn export_plaintext(state: State<AppState>) -> Result<String, String> {
    let session = state.session.lock().unwrap();
    if !session.unlocked {
        return Err(StoreError::Locked.to_string());
    }
    let payload = PlainExport {
        name: session.name.clone(),
        exported_at: store::now_secs(),
        entries: session.data.entries.clone(),
    };
    serde_json::to_string_pretty(&payload).map_err(err)
}

/// Import a plaintext export (JSON). Merges by generating new IDs.
#[tauri::command]
fn import_plaintext(state: State<AppState>, json: String) -> Result<usize, String> {
    let parsed: PlainExport = serde_json::from_str(&json)
        .map_err(|e| format!("could not parse import file: {e}"))?;
    let mut count = 0;
    {
        let mut session = state.session.lock().unwrap();
        if !session.unlocked {
            return Err(StoreError::Locked.to_string());
        }
        let now = store::now_secs();
        for mut c in parsed.entries {
            c.id = store::new_id();
            if c.created_at == 0 {
                c.created_at = now;
            }
            c.updated_at = now;
            session.data.entries.push(c);
            count += 1;
        }
    }
    persist(&state)?;
    Ok(count)
}

#[cfg_attr(mobile, tauri::mobile_entry_point)]
pub fn run() {
    tauri::Builder::default()
        .plugin(tauri_plugin_opener::init())
        .plugin(tauri_plugin_clipboard_manager::init())
        .plugin(tauri_plugin_dialog::init())
        .plugin(tauri_plugin_fs::init())
        .manage(AppState::default())
        .invoke_handler(tauri::generate_handler![
            get_status,
            create_vault,
            unlock,
            lock,
            list_entries,
            upsert_entry,
            delete_entry,
            change_master_password,
            export_encrypted,
            export_plaintext,
            import_plaintext,
        ])
        .run(tauri::generate_context!())
        .expect("error while running tauri application");
}
