{"content": "import { useState } from "react";
import { writeText } from "@tauri-apps/plugin-clipboard-manager";
import { save } from "@tauri-apps/plugin-dialog";
import { writeTextFile } from "@tauri-apps/plugin-fs";
import { api } from "@/lib/api";
import { passwordStrength } from "@/lib/password";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { useToast } from "@/components/toast";
import {
  ShieldCheck,
  KeyRound,
  Copy,
  Download,
  Eye,
  EyeOff,
  Lock,
  ArrowRight,
} from "lucide-react";
import { cn } from "@/lib/utils";

type Step = "welcome" | "password" | "recovery" | "done";

export function Onboarding({ onComplete }: { onComplete: () => void }) {
  const toast = useToast();
  const [step, setStep] = useState<Step>("welcome");
  const [name, setName] = useState("ROVault");
  const [password, setPassword] = useState("");
  const [confirm, setConfirm] = useState("");
  const [show, setShow] = useState(false);
  const [recoveryKey, setRecoveryKey] = useState("");
  const [saved, setSaved] = useState(false);
  const [busy, setBusy] = useState(false);

  const strength = passwordStrength(password);

  async function createVault() {
    if (password.length < 8) {
      toast("Master password must be at least 8 characters", "error");
      return;
    }
    if (password !== confirm) {
      toast("Passwords do not match", "error");
      return;
    }
    setBusy(true);
    try {
      const res = await api.createVault(name.trim() || "ROVault", password);
      setRecoveryKey(res.recovery_key);
      setStep("recovery");
    } catch (e) {
      toast(String(e), "error");
    } finally {
      setBusy(false);
    }
  }

  async function copyKey() {
    await writeText(recoveryKey);
    toast("Recovery key copied to clipboard", "success");
  }

  async function downloadKey() {
    try {
      const path = await save({
        defaultPath: "rovault-recovery-key.txt",
        filters: [{ name: "Text", extensions: ["txt"] }],
      });
      if (path) {
        await writeTextFile(
          path,
          `ROVault Recovery Key\nVault: ${name}\n\n${recoveryKey}\n\nKeep this somewhere safe and offline. It can unlock your vault if you forget your master password.`
        );
        toast("Recovery key saved", "success");
      }
    } catch (e) {
      toast(String(e), "error");
    }
  }

  return (
    <div className="flex h-full w-full items-center justify-center bg-gradient-to-br from-background via-background to-accent/30 p-6">
      <div className="w-full max-w-md animate-fade-in">
        <div className="mb-8 flex flex-col items-center text-center">
          <div className="mb-4 flex h-16 w-16 items-center justify-center rounded-2xl bg-primary text-primary-foreground shadow-lg">
            <Lock className="h-8 w-8" />
          </div>
          <h1 className="text-2xl font-bold tracking-tight">ROVault</h1>
          <p className="text-sm text-muted-foreground">
            Your local, fully-encrypted credential vault
          </p>
        </div>

        <div className="rounded-xl border bg-card p-6 shadow-sm">
          {step === "welcome" && (
            <div className="space-y-5">
              <div className="flex items-start gap-3">
                <ShieldCheck className="mt-0.5 h-5 w-5 shrink-0 text-primary" />
                <div>
                  <h2 className="font-semibold">Welcome</h2>
                  <p className="text-sm text-muted-foreground">
                    Everything is stored encrypted on this device. Nothing is
                    sent anywhere. Let's set up your vault.
                  </p>
                </div>
              </div>
              <div className="space-y-2">
                <Label htmlFor="vault-name">Name your vault</Label>
                <Input
                  id="vault-name"
                  value={name}
                  onChange={(e) => setName(e.target.value)}
                  placeholder="ROVault"
                  autoFocus
                />
              </div>
              <Button className="w-full" onClick={() => setStep("password")}>
                Continue <ArrowRight className="h-4 w-4" />
              </Button>
            </div>
          )}

          {step === "password" && (
            <div className="space-y-5">
              <div className="flex items-start gap-3">
                <KeyRound className="mt-0.5 h-5 w-5 shrink-0 text-primary" />
                <div>
                  <h2 className="font-semibold">Create a master password</h2>
                  <p className="text-sm text-muted-foreground">
                    This unlocks your vault. Choose something strong you won't
                    forget — there's no way to reset it without your recovery
                    key.
                  </p>
                </div>
              </div>
              <div className="space-y-2">
                <Label htmlFor="pw">Master password</Label>
                <div className="relative">
                  <Input
                    id="pw"
                    type={show ? "text" : "password"}
                    value={password}
                    onChange={(e) => setPassword(e.target.value)}
                    autoFocus
                  />
                  <button
                    type="button"
                    onClick={() => setShow((s) => !s)}
                    className="absolute right-2 top-1/2 -translate-y-1/2 text-muted-foreground hover:text-foreground"
                    aria-label={show ? "Hide password" : "Show password"}
                  >
                    {show ? <EyeOff className="h-4 w-4" /> : <Eye className="h-4 w-4" />}
                  </button>
                </div>
                {password && (
                  <div className="flex items-center gap-2">
                    <div className="flex h-1.5 flex-1 gap-1">
                      {[0, 1, 2, 3].map((i) => (
                        <div
                          key={i}
                          className={cn(
                            "h-full flex-1 rounded-full bg-muted",
                            i < strength.score &&
                              (strength.score <= 1
                                ? "bg-destructive"
                                : strength.score <= 2
                                ? "bg-yellow-500"
                                : "bg-green-500")
                          )}
                        />
                      ))}
                    </div>
                    <span className="text-xs text-muted-foreground">
                      {strength.label}
                    </span>
                  </div>
                )}
              </div>
              <div className="space-y-2">
                <Label htmlFor="pw2">Confirm password</Label>
                <Input
                  id="pw2"
                  type={show ? "text" : "password"}
                  value={confirm}
                  onChange={(e) => setConfirm(e.target.value)}
                />
              </div>
              <div className="flex gap-2">
                <Button
                  variant="outline"
                  className="flex-1"
                  onClick={() => setStep("welcome")}
                >
                  Back
                </Button>
                <Button className="flex-1" onClick={createVault} disabled={busy}>
                  {busy ? "Creating…" : "Create vault"}
                </Button>
              </div>
            </div>
          )}

          {step === "recovery" && (
            <div className="space-y-5">
              <div className="flex items-start gap-3">
                <KeyRound className="mt-0.5 h-5 w-5 shrink-0 text-primary" />
                <div>
                  <h2 className="font-semibold">Save your recovery key</h2>
                  <p className="text-sm text-muted-foreground">
                    This is shown <strong>once</strong>. Store it somewhere safe
                    and separate from this device. It's the only way in if you
                    forget your master password.
                  </p>
                </div>
              </div>
              <div className="rounded-lg border border-dashed bg-muted/50 p-4 text-center font-mono text-sm tracking-wide">
                {recoveryKey}
              </div>
              <div className="flex gap-2">
                <Button variant="outline" className="flex-1" onClick={copyKey}>
                  <Copy className="h-4 w-4" /> Copy
                </Button>
                <Button variant="outline" className="flex-1" onClick={downloadKey}>
                  <Download className="h-4 w-4" /> Download
                </Button>
              </div>
              <label className="flex cursor-pointer items-start gap-2 text-sm">
                <input
                  type="checkbox"
                  checked={saved}
                  onChange={(e) => setSaved(e.target.checked)}
                  className="mt-0.5 h-4 w-4 accent-[hsl(var(--primary))]"
                />
                <span className="text-muted-foreground">
                  I've saved my recovery key somewhere safe. I understand it
                  cannot be shown again.
                </span>
              </label>
              <Button
                className="w-full"
                disabled={!saved}
                onClick={() => setStep("done")}
              >
                Finish setup
              </Button>
            </div>
          )}

          {step === "done" && (
            <div className="space-y-5 text-center">
              <div className="mx-auto flex h-12 w-12 items-center justify-center rounded-full bg-green-500/15">
                <ShieldCheck className="h-6 w-6 text-green-500" />
              </div>
              <div>
                <h2 className="font-semibold">You're all set</h2>
                <p className="text-sm text-muted-foreground">
                  Your vault is encrypted and ready. Let's add your first
                  credential.
                </p>
              </div>
              <Button className="w-full" onClick={onComplete}>
                Open dashboard <ArrowRight className="h-4 w-4" />
              </Button>
            </div>
          )}
        </div>
      </div>
    </div>
  );
}
