{"content": "import { useState } from "react";
import { api } from "@/lib/api";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { useToast } from "@/components/toast";
import { Lock, Eye, EyeOff, KeyRound } from "lucide-react";

export function LockScreen({
  vaultName,
  onUnlocked,
}: {
  vaultName: string;
  onUnlocked: () => void;
}) {
  const toast = useToast();
  const [mode, setMode] = useState<"password" | "recovery">("password");
  const [value, setValue] = useState("");
  const [show, setShow] = useState(false);
  const [busy, setBusy] = useState(false);

  async function submit(e: React.FormEvent) {
    e.preventDefault();
    if (!value) return;
    setBusy(true);
    try {
      await api.unlock(value, mode === "recovery");
      setValue("");
      onUnlocked();
    } catch {
      toast(
        mode === "recovery"
          ? "Invalid recovery key"
          : "Incorrect master password",
        "error"
      );
    } finally {
      setBusy(false);
    }
  }

  return (
    <div className="flex h-full w-full items-center justify-center bg-gradient-to-br from-background via-background to-accent/30 p-6">
      <form onSubmit={submit} className="w-full max-w-sm animate-fade-in">
        <div className="mb-8 flex flex-col items-center text-center">
          <div className="mb-4 flex h-16 w-16 items-center justify-center rounded-2xl bg-primary text-primary-foreground shadow-lg">
            <Lock className="h-8 w-8" />
          </div>
          <h1 className="text-xl font-bold tracking-tight">{vaultName || "ROVault"}</h1>
          <p className="text-sm text-muted-foreground">
            {mode === "password"
              ? "Enter your master password to unlock"
              : "Enter your recovery key to unlock"}
          </p>
        </div>

        <div className="space-y-4 rounded-xl border bg-card p-6 shadow-sm">
          <div className="space-y-2">
            <Label htmlFor="unlock">
              {mode === "password" ? "Master password" : "Recovery key"}
            </Label>
            <div className="relative">
              <Input
                id="unlock"
                type={mode === "recovery" || show ? "text" : "password"}
                value={value}
                onChange={(e) => setValue(e.target.value)}
                placeholder={
                  mode === "recovery" ? "XXXX-XXXX-XXXX-…" : "••••••••"
                }
                autoFocus
                className={mode === "recovery" ? "font-mono" : ""}
              />
              {mode === "password" && (
                <button
                  type="button"
                  onClick={() => setShow((s) => !s)}
                  className="absolute right-2 top-1/2 -translate-y-1/2 text-muted-foreground hover:text-foreground"
                  aria-label={show ? "Hide" : "Show"}
                >
                  {show ? <EyeOff className="h-4 w-4" /> : <Eye className="h-4 w-4" />}
                </button>
              )}
            </div>
          </div>

          <Button type="submit" className="w-full" disabled={busy}>
            {busy ? "Unlocking…" : "Unlock"}
          </Button>

          <button
            type="button"
            onClick={() => {
              setMode((m) => (m === "password" ? "recovery" : "password"));
              setValue("");
            }}
            className="flex w-full items-center justify-center gap-1.5 text-xs text-muted-foreground hover:text-foreground"
          >
            <KeyRound className="h-3.5 w-3.5" />
            {mode === "password"
              ? "Forgot password? Use recovery key"
              : "Use master password instead"}
          </button>
        </div>
      </form>
    </div>
  );
}
