{"content": "import { useEffect, useState } from "react";
import { type Credential, emptyCredential } from "@/lib/api";
import { generatePassword, passwordStrength } from "@/lib/password";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogDescription,
  DialogFooter,
} from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import { Eye, EyeOff, RefreshCw, Star } from "lucide-react";
import { cn } from "@/lib/utils";

const CATEGORIES = ["Social", "Email", "Banking", "Work", "Shopping", "Other"];

export function CredentialDialog({
  open,
  initial,
  onClose,
  onSave,
}: {
  open: boolean;
  initial: Credential | null;
  onClose: () => void;
  onSave: (c: Credential) => Promise<void>;
}) {
  const [form, setForm] = useState<Credential>(emptyCredential());
  const [show, setShow] = useState(false);
  const [busy, setBusy] = useState(false);

  useEffect(() => {
    if (open) {
      setForm(initial ? { ...initial } : emptyCredential());
      setShow(false);
    }
  }, [open, initial]);

  const set = (k: keyof Credential, v: string | boolean) =>
    setForm((f) => ({ ...f, [k]: v }));

  const strength = passwordStrength(form.password);

  async function handleSave() {
    if (!form.provider.trim()) return;
    setBusy(true);
    try {
      await onSave(form);
      onClose();
    } finally {
      setBusy(false);
    }
  }

  return (
    <Dialog open={open} onOpenChange={(o) => !o && onClose()}>
      <DialogContent className="max-h-[90vh] overflow-y-auto">
        <DialogHeader>
          <DialogTitle>{initial ? "Edit credential" : "Add credential"}</DialogTitle>
          <DialogDescription>
            Stored encrypted. Only visible inside ROVault.
          </DialogDescription>
        </DialogHeader>

        <div className="grid gap-4">
          <div className="grid gap-2">
            <Label htmlFor="provider">Provider / Service *</Label>
            <Input
              id="provider"
              value={form.provider}
              onChange={(e) => set("provider", e.target.value)}
              placeholder="Facebook"
              autoFocus
            />
          </div>

          <div className="grid gap-2">
            <Label htmlFor="username">Username / Email</Label>
            <Input
              id="username"
              value={form.username}
              onChange={(e) => set("username", e.target.value)}
              placeholder="you@example.com"
            />
          </div>

          <div className="grid gap-2">
            <Label htmlFor="password">Password</Label>
            <div className="flex gap-2">
              <div className="relative flex-1">
                <Input
                  id="password"
                  type={show ? "text" : "password"}
                  value={form.password}
                  onChange={(e) => set("password", e.target.value)}
                  className="pr-9 font-mono"
                />
                <button
                  type="button"
                  onClick={() => setShow((s) => !s)}
                  className="absolute right-2 top-1/2 -translate-y-1/2 text-muted-foreground hover:text-foreground"
                  aria-label={show ? "Hide" : "Show"}
                >
                  {show ? <EyeOff className="h-4 w-4" /> : <Eye className="h-4 w-4" />}
                </button>
              </div>
              <Button
                type="button"
                variant="outline"
                size="icon"
                title="Generate strong password"
                onClick={() => {
                  set("password", generatePassword(20));
                  setShow(true);
                }}
              >
                <RefreshCw className="h-4 w-4" />
              </Button>
            </div>
            {form.password && (
              <div className="flex items-center gap-2">
                <div className="flex h-1.5 flex-1 gap-1">
                  {[0, 1, 2, 3].map((i) => (
                    <div
                      key={i}
                      className={cn(
                        "h-full flex-1 rounded-full bg-muted",
                        i < strength.score &&
                          (strength.score <= 1
                            ? "bg-destructive"
                            : strength.score <= 2
                            ? "bg-yellow-500"
                            : "bg-green-500")
                      )}
                    />
                  ))}
                </div>
                <span className="text-xs text-muted-foreground">
                  {strength.label}
                </span>
              </div>
            )}
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div className="grid gap-2">
              <Label htmlFor="category">Category</Label>
              <select
                id="category"
                value={form.category}
                onChange={(e) => set("category", e.target.value)}
                className="flex h-10 w-full rounded-md border border-input bg-background px-3 py-2 text-sm focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2"
              >
                <option value="">Uncategorized</option>
                {CATEGORIES.map((c) => (
                  <option key={c} value={c}>
                    {c}
                  </option>
                ))}
              </select>
            </div>
            <div className="grid gap-2">
              <Label htmlFor="url">Website URL</Label>
              <Input
                id="url"
                value={form.url}
                onChange={(e) => set("url", e.target.value)}
                placeholder="https://…"
              />
            </div>
          </div>

          <div className="grid gap-2">
            <Label htmlFor="notes">Notes</Label>
            <Textarea
              id="notes"
              value={form.notes}
              onChange={(e) => set("notes", e.target.value)}
              placeholder="Recovery codes, security questions, etc."
            />
          </div>

          <button
            type="button"
            onClick={() => set("favorite", !form.favorite)}
            className="flex items-center gap-2 text-sm text-muted-foreground hover:text-foreground"
          >
            <Star
              className={cn(
                "h-4 w-4",
                form.favorite && "fill-yellow-400 text-yellow-400"
              )}
            />
            {form.favorite ? "Favorited" : "Mark as favorite"}
          </button>
        </div>

        <DialogFooter>
          <Button variant="outline" onClick={onClose}>
            Cancel
          </Button>
          <Button onClick={handleSave} disabled={busy || !form.provider.trim()}>
            {busy ? "Saving…" : "Save"}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}
