{"content": "import { useState } from "react";
import { api } from "@/lib/api";
import { useTheme } from "@/components/theme-provider";
import { useToast } from "@/components/toast";
import { save, open, ask } from "@tauri-apps/plugin-dialog";
import { writeTextFile, readTextFile } from "@tauri-apps/plugin-fs";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogDescription,
} from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import {
  Sun,
  Moon,
  Monitor,
  Download,
  Upload,
  ShieldAlert,
  KeyRound,
  Timer,
} from "lucide-react";
import { cn } from "@/lib/utils";

const AUTOLOCK_KEY = "rovault-autolock-min";

export function SettingsDialog({
  open: isOpen,
  onClose,
  onImported,
}: {
  open: boolean;
  onClose: () => void;
  onImported: () => void;
}) {
  const { theme, setTheme } = useTheme();
  const toast = useToast();
  const [tab, setTab] = useState<"appearance" | "security" | "data">(
    "appearance"
  );

  const [curPw, setCurPw] = useState("");
  const [newPw, setNewPw] = useState("");
  const [confirmPw, setConfirmPw] = useState("");
  const [autolock, setAutolock] = useState(
    () => Number(localStorage.getItem(AUTOLOCK_KEY)) || 5
  );

  async function changePassword() {
    if (newPw.length < 8) return toast("New password too short", "error");
    if (newPw !== confirmPw) return toast("Passwords do not match", "error");
    try {
      await api.changeMasterPassword(curPw, newPw);
      setCurPw("");
      setNewPw("");
      setConfirmPw("");
      toast("Master password changed", "success");
    } catch (e) {
      toast(String(e), "error");
    }
  }

  async function exportEncrypted() {
    try {
      const data = await api.exportEncrypted();
      const path = await save({
        defaultPath: "rovault-backup.rovault",
        filters: [{ name: "ROVault backup", extensions: ["rovault", "json"] }],
      });
      if (path) {
        await writeTextFile(path, data);
        toast("Encrypted backup saved", "success");
      }
    } catch (e) {
      toast(String(e), "error");
    }
  }

  async function exportPlaintext() {
    const confirmed = await ask(
      "This exports an UNENCRYPTED file readable by anyone who opens it. Only do this to migrate your data. Continue?",
      { title: "Plaintext export", kind: "warning" }
    );
    if (!confirmed) return;
    try {
      const data = await api.exportPlaintext();
      const path = await save({
        defaultPath: "rovault-plaintext-export.json",
        filters: [{ name: "JSON", extensions: ["json"] }],
      });
      if (path) {
        await writeTextFile(path, data);
        toast("Plaintext export saved — keep it safe!", "success");
      }
    } catch (e) {
      toast(String(e), "error");
    }
  }

  async function importData() {
    try {
      const path = await open({
        multiple: false,
        filters: [{ name: "JSON", extensions: ["json"] }],
      });
      if (typeof path !== "string") return;
      const contents = await readTextFile(path);
      const count = await api.importPlaintext(contents);
      toast(`Imported ${count} credential(s)`, "success");
      onImported();
    } catch (e) {
      toast(String(e), "error");
    }
  }

  const themeOptions = [
    { value: "light", label: "Light", icon: Sun },
    { value: "dark", label: "Dark", icon: Moon },
    { value: "system", label: "System", icon: Monitor },
  ] as const;

  return (
    <Dialog open={isOpen} onOpenChange={(o) => !o && onClose()}>
      <DialogContent className="max-h-[90vh] overflow-y-auto sm:max-w-xl">
        <DialogHeader>
          <DialogTitle>Settings</DialogTitle>
          <DialogDescription>
            Preferences, security, and data management.
          </DialogDescription>
        </DialogHeader>

        <div className="flex gap-2 border-b">
          {(["appearance", "security", "data"] as const).map((t) => (
            <button
              key={t}
              onClick={() => setTab(t)}
              className={cn(
                "border-b-2 px-3 py-2 text-sm font-medium capitalize transition-colors",
                tab === t
                  ? "border-primary text-foreground"
                  : "border-transparent text-muted-foreground hover:text-foreground"
              )}
            >
              {t}
            </button>
          ))}
        </div>

        {tab === "appearance" && (
          <div className="space-y-4 py-2">
            <div className="space-y-2">
              <Label>Theme</Label>
              <div className="grid grid-cols-3 gap-2">
                {themeOptions.map((opt) => (
                  <button
                    key={opt.value}
                    onClick={() => setTheme(opt.value)}
                    className={cn(
                      "flex flex-col items-center gap-2 rounded-lg border p-4 text-sm transition-colors hover:bg-accent",
                      theme === opt.value
                        ? "border-primary bg-accent"
                        : "border-border"
                    )}
                  >
                    <opt.icon className="h-5 w-5" />
                    {opt.label}
                  </button>
                ))}
              </div>
            </div>
            <div className="space-y-2">
              <Label className="flex items-center gap-2">
                <Timer className="h-4 w-4" /> Auto-lock after (minutes of
                inactivity)
              </Label>
              <Input
                type="number"
                min={0}
                value={autolock}
                onChange={(e) => {
                  const v = Number(e.target.value);
                  setAutolock(v);
                  localStorage.setItem(AUTOLOCK_KEY, String(v));
                }}
              />
              <p className="text-xs text-muted-foreground">
                Set to 0 to disable. The vault also locks when you quit the app.
              </p>
            </div>
          </div>
        )}

        {tab === "security" && (
          <div className="space-y-4 py-2">
            <div className="flex items-start gap-2 rounded-lg border border-primary/30 bg-accent/40 p-3 text-sm">
              <KeyRound className="mt-0.5 h-4 w-4 shrink-0 text-primary" />
              <span className="text-muted-foreground">
                Changing your master password keeps your recovery key valid.
              </span>
            </div>
            <div className="grid gap-2">
              <Label htmlFor="curpw">Current password</Label>
              <Input
                id="curpw"
                type="password"
                value={curPw}
                onChange={(e) => setCurPw(e.target.value)}
              />
            </div>
            <div className="grid gap-2">
              <Label htmlFor="newpw">New password</Label>
              <Input
                id="newpw"
                type="password"
                value={newPw}
                onChange={(e) => setNewPw(e.target.value)}
              />
            </div>
            <div className="grid gap-2">
              <Label htmlFor="cfpw">Confirm new password</Label>
              <Input
                id="cfpw"
                type="password"
                value={confirmPw}
                onChange={(e) => setConfirmPw(e.target.value)}
              />
            </div>
            <Button onClick={changePassword} disabled={!curPw || !newPw}>
              Change password
            </Button>
          </div>
        )}

        {tab === "data" && (
          <div className="space-y-4 py-2">
            <div className="space-y-2">
              <Label>Backup & restore</Label>
              <div className="grid gap-2">
                <Button variant="outline" onClick={exportEncrypted}>
                  <Download className="h-4 w-4" /> Export encrypted backup
                  (.rovault)
                </Button>
                <Button variant="outline" onClick={importData}>
                  <Upload className="h-4 w-4" /> Import from file
                </Button>
              </div>
              <p className="text-xs text-muted-foreground">
                The encrypted backup is safe to store anywhere — useless without
                your password or recovery key.
              </p>
            </div>
            <div className="space-y-2 rounded-lg border border-destructive/40 p-3">
              <Label className="flex items-center gap-2 text-destructive">
                <ShieldAlert className="h-4 w-4" /> Danger zone
              </Label>
              <Button variant="destructive" onClick={exportPlaintext}>
                <Download className="h-4 w-4" /> Export UNENCRYPTED (plaintext)
              </Button>
              <p className="text-xs text-muted-foreground">
                Only for migrating out. This file is readable by anyone.
              </p>
            </div>
          </div>
        )}
      </DialogContent>
    </Dialog>
  );
}

export function getAutolockMinutes(): number {
  return Number(localStorage.getItem(AUTOLOCK_KEY)) || 5;
}
