{"content": "import { useEffect, useMemo, useState, useCallback } from "react";
import { api, type Credential } from "@/lib/api";
import { writeText } from "@tauri-apps/plugin-clipboard-manager";
import { useToast } from "@/components/toast";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Badge } from "@/components/ui/badge";
import { CredentialDialog } from "./CredentialDialog";
import { SettingsDialog, getAutolockMinutes } from "./Settings";
import { cn } from "@/lib/utils";
import {
  Lock,
  Plus,
  Search,
  Settings as SettingsIcon,
  Copy,
  Eye,
  EyeOff,
  Star,
  Trash2,
  Pencil,
  Globe,
  LayoutGrid,
  Mail,
  CreditCard,
  Briefcase,
  ShoppingBag,
  Users,
  Folder,
} from "lucide-react";
import { open as openUrl } from "@tauri-apps/plugin-opener";

const CATEGORY_ICONS: Record<string, typeof Globe> = {
  Social: Users,
  Email: Mail,
  Banking: CreditCard,
  Work: Briefcase,
  Shopping: ShoppingBag,
  Other: Folder,
};

function providerInitial(name: string) {
  return (name.trim()[0] || "?").toUpperCase();
}

// Deterministic pleasant hue from provider name for the card avatar.
function hueFor(name: string) {
  let h = 0;
  for (let i = 0; i < name.length; i++) h = (h * 31 + name.charCodeAt(i)) % 360;
  return h;
}

export function Dashboard({ onLock }: { onLock: () => void }) {
  const toast = useToast();
  const [entries, setEntries] = useState<Credential[]>([]);
  const [search, setSearch] = useState("");
  const [category, setCategory] = useState<string>("All");
  const [dialogOpen, setDialogOpen] = useState(false);
  const [editing, setEditing] = useState<Credential | null>(null);
  const [settingsOpen, setSettingsOpen] = useState(false);
  const [revealed, setRevealed] = useState<Set<string>>(new Set());

  const refresh = useCallback(async () => {
    try {
      setEntries(await api.listEntries());
    } catch (e) {
      toast(String(e), "error");
    }
  }, [toast]);

  useEffect(() => {
    refresh();
  }, [refresh]);

  // Auto-lock on inactivity.
  useEffect(() => {
    const mins = getAutolockMinutes();
    if (!mins) return;
    let timer: ReturnType<typeof setTimeout>;
    const reset = () => {
      clearTimeout(timer);
      timer = setTimeout(async () => {
        await api.lock();
        onLock();
      }, mins * 60 * 1000);
    };
    const events = ["mousemove", "keydown", "click", "scroll"];
    events.forEach((e) => window.addEventListener(e, reset));
    reset();
    return () => {
      clearTimeout(timer);
      events.forEach((e) => window.removeEventListener(e, reset));
    };
  }, [onLock]);

  const categories = useMemo(() => {
    const set = new Set<string>();
    entries.forEach((e) => e.category && set.add(e.category));
    return Array.from(set).sort();
  }, [entries]);

  const filtered = useMemo(() => {
    const q = search.toLowerCase();
    return entries
      .filter((e) => {
        if (category === "Favorites") return e.favorite;
        if (category !== "All" && e.category !== category) return false;
        return true;
      })
      .filter(
        (e) =>
          !q ||
          e.provider.toLowerCase().includes(q) ||
          e.username.toLowerCase().includes(q) ||
          e.url.toLowerCase().includes(q)
      )
      .sort((a, b) => a.provider.localeCompare(b.provider));
  }, [entries, search, category]);

  async function copy(text: string, label: string) {
    if (!text) return;
    await writeText(text);
    toast(`${label} copied`, "success");
    // Auto-clear clipboard after 20s for safety.
    setTimeout(async () => {
      try {
        await writeText("");
      } catch {
        /* ignore */
      }
    }, 20000);
  }

  function toggleReveal(id: string) {
    setRevealed((prev) => {
      const next = new Set(prev);
      next.has(id) ? next.delete(id) : next.add(id);
      return next;
    });
  }

  async function save(c: Credential) {
    await api.upsertEntry(c);
    await refresh();
    toast(c.id ? "Credential updated" : "Credential added", "success");
  }

  async function remove(c: Credential) {
    await api.deleteEntry(c.id);
    await refresh();
    toast("Credential deleted", "success");
  }

  const navItems = [
    { key: "All", label: "All items", icon: LayoutGrid },
    { key: "Favorites", label: "Favorites", icon: Star },
  ];

  return (
    <div className="flex h-full w-full overflow-hidden">
      {/* Sidebar */}
      <aside className="flex w-60 shrink-0 flex-col border-r bg-card/50">
        <div className="flex items-center gap-2 p-4">
          <div className="flex h-9 w-9 items-center justify-center rounded-lg bg-primary text-primary-foreground">
            <Lock className="h-4 w-4" />
          </div>
          <span className="font-semibold">ROVault</span>
        </div>

        <nav className="flex-1 space-y-1 overflow-y-auto p-2" aria-label="Categories">
          {navItems.map((item) => (
            <SidebarButton
              key={item.key}
              active={category === item.key}
              onClick={() => setCategory(item.key)}
              icon={item.icon}
              label={item.label}
              count={
                item.key === "Favorites"
                  ? entries.filter((e) => e.favorite).length
                  : entries.length
              }
            />
          ))}

          {categories.length > 0 && (
            <div className="px-3 pb-1 pt-4 text-xs font-medium uppercase tracking-wider text-muted-foreground">
              Categories
            </div>
          )}
          {categories.map((c) => (
            <SidebarButton
              key={c}
              active={category === c}
              onClick={() => setCategory(c)}
              icon={CATEGORY_ICONS[c] || Folder}
              label={c}
              count={entries.filter((e) => e.category === c).length}
            />
          ))}
        </nav>

        <div className="space-y-1 border-t p-2">
          <SidebarButton
            icon={SettingsIcon}
            label="Settings"
            onClick={() => setSettingsOpen(true)}
          />
          <SidebarButton
            icon={Lock}
            label="Lock vault"
            onClick={async () => {
              await api.lock();
              onLock();
            }}
          />
        </div>
      </aside>

      {/* Main */}
      <main className="flex flex-1 flex-col overflow-hidden">
        <header className="flex items-center gap-3 border-b p-4">
          <div className="relative flex-1">
            <Search className="absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-muted-foreground" />
            <Input
              value={search}
              onChange={(e) => setSearch(e.target.value)}
              placeholder="Search credentials…"
              className="pl-9"
              aria-label="Search credentials"
            />
          </div>
          <Button
            onClick={() => {
              setEditing(null);
              setDialogOpen(true);
            }}
          >
            <Plus className="h-4 w-4" /> Add
          </Button>
        </header>

        <div className="flex-1 overflow-y-auto p-4">
          {filtered.length === 0 ? (
            <EmptyState
              hasAny={entries.length > 0}
              onAdd={() => {
                setEditing(null);
                setDialogOpen(true);
              }}
            />
          ) : (
            <div className="grid grid-cols-1 gap-4 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4">
              {filtered.map((c) => {
                const isRevealed = revealed.has(c.id);
                const hue = hueFor(c.provider);
                return (
                  <div
                    key={c.id}
                    className="group flex flex-col rounded-lg border bg-card p-4 shadow-sm transition-shadow hover:shadow-md"
                  >
                    <div className="flex items-start justify-between">
                      <div className="flex items-center gap-3">
                        <div
                          className="flex h-10 w-10 items-center justify-center rounded-lg font-semibold text-white"
                          style={{ backgroundColor: `hsl(${hue} 60% 50%)` }}
                        >
                          {providerInitial(c.provider)}
                        </div>
                        <div className="min-w-0">
                          <div className="flex items-center gap-1.5">
                            <span className="truncate font-medium">
                              {c.provider}
                            </span>
                            {c.favorite && (
                              <Star className="h-3.5 w-3.5 shrink-0 fill-yellow-400 text-yellow-400" />
                            )}
                          </div>
                          {c.category && (
                            <Badge className="mt-0.5 text-[10px]">
                              {c.category}
                            </Badge>
                          )}
                        </div>
                      </div>
                      <div className="flex gap-1 opacity-0 transition-opacity group-hover:opacity-100">
                        <button
                          onClick={() => {
                            setEditing(c);
                            setDialogOpen(true);
                          }}
                          className="rounded p-1 text-muted-foreground hover:bg-accent hover:text-foreground"
                          aria-label="Edit"
                        >
                          <Pencil className="h-4 w-4" />
                        </button>
                        <button
                          onClick={() => remove(c)}
                          className="rounded p-1 text-muted-foreground hover:bg-destructive/10 hover:text-destructive"
                          aria-label="Delete"
                        >
                          <Trash2 className="h-4 w-4" />
                        </button>
                      </div>
                    </div>

                    <div className="mt-4 space-y-2 text-sm">
                      {c.username && (
                        <Field
                          label="Username"
                          value={c.username}
                          onCopy={() => copy(c.username, "Username")}
                        />
                      )}
                      <Field
                        label="Password"
                        value={isRevealed ? c.password : "••••••••••"}
                        mono
                        onCopy={() => copy(c.password, "Password")}
                        trailing={
                          <button
                            onClick={() => toggleReveal(c.id)}
                            className="text-muted-foreground hover:text-foreground"
                            aria-label={isRevealed ? "Hide" : "Reveal"}
                          >
                            {isRevealed ? (
                              <EyeOff className="h-3.5 w-3.5" />
                            ) : (
                              <Eye className="h-3.5 w-3.5" />
                            )}
                          </button>
                        }
                      />
                    </div>

                    {c.url && (
                      <button
                        onClick={() => openUrl(c.url).catch(() => {})}
                        className="mt-3 flex items-center gap-1 truncate text-xs text-primary hover:underline"
                      >
                        <Globe className="h-3 w-3 shrink-0" />
                        <span className="truncate">{c.url}</span>
                      </button>
                    )}
                  </div>
                );
              })}
            </div>
          )}
        </div>
      </main>

      <CredentialDialog
        open={dialogOpen}
        initial={editing}
        onClose={() => setDialogOpen(false)}
        onSave={save}
      />
      <SettingsDialog
        open={settingsOpen}
        onClose={() => setSettingsOpen(false)}
        onImported={refresh}
      />
    </div>
  );
}

function SidebarButton({
  icon: Icon,
  label,
  count,
  active,
  onClick,
}: {
  icon: typeof Globe;
  label: string;
  count?: number;
  active?: boolean;
  onClick: () => void;
}) {
  return (
    <button
      onClick={onClick}
      className={cn(
        "flex w-full items-center gap-3 rounded-md px-3 py-2 text-sm transition-colors",
        active
          ? "bg-primary/10 font-medium text-primary"
          : "text-muted-foreground hover:bg-accent hover:text-foreground"
      )}
    >
      <Icon className="h-4 w-4 shrink-0" />
      <span className="flex-1 text-left">{label}</span>
      {count !== undefined && (
        <span className="text-xs text-muted-foreground">{count}</span>
      )}
    </button>
  );
}

function Field({
  label,
  value,
  mono,
  onCopy,
  trailing,
}: {
  label: string;
  value: string;
  mono?: boolean;
  onCopy: () => void;
  trailing?: React.ReactNode;
}) {
  return (
    <div className="flex items-center gap-2 rounded-md bg-muted/50 px-2.5 py-1.5">
      <div className="min-w-0 flex-1">
        <div className="text-[10px] uppercase tracking-wide text-muted-foreground">
          {label}
        </div>
        <div className={cn("truncate", mono && "font-mono text-xs")}>
          {value}
        </div>
      </div>
      {trailing}
      <button
        onClick={onCopy}
        className="text-muted-foreground hover:text-foreground"
        aria-label={`Copy ${label}`}
      >
        <Copy className="h-3.5 w-3.5" />
      </button>
    </div>
  );
}

function EmptyState({
  hasAny,
  onAdd,
}: {
  hasAny: boolean;
  onAdd: () => void;
}) {
  return (
    <div className="flex h-full min-h-[300px] flex-col items-center justify-center text-center">
      <div className="mb-4 flex h-14 w-14 items-center justify-center rounded-2xl bg-muted">
        <LayoutGrid className="h-6 w-6 text-muted-foreground" />
      </div>
      <h3 className="font-semibold">
        {hasAny ? "No matches" : "Your vault is empty"}
      </h3>
      <p className="mb-4 max-w-xs text-sm text-muted-foreground">
        {hasAny
          ? "Try a different search or category."
          : "Add your first credential to keep it safe and always within reach."}
      </p>
      {!hasAny && (
        <Button onClick={onAdd}>
          <Plus className="h-4 w-4" /> Add credential
        </Button>
      )}
    </div>
  );
}
