{"content": "import { useEffect, useState } from "react";
import { api } from "@/lib/api";
import { Onboarding } from "@/screens/Onboarding";
import { LockScreen } from "@/screens/LockScreen";
import { Dashboard } from "@/screens/Dashboard";
import { Lock } from "lucide-react";

type Phase = "loading" | "onboarding" | "locked" | "unlocked";

export default function App() {
  const [phase, setPhase] = useState<Phase>("loading");
  const [vaultName, setVaultName] = useState("ROVault");

  async function checkStatus() {
    try {
      const s = await api.getStatus();
      setVaultName(s.name || "ROVault");
      if (!s.exists) setPhase("onboarding");
      else if (s.unlocked) setPhase("unlocked");
      else setPhase("locked");
    } catch {
      setPhase("onboarding");
    }
  }

  useEffect(() => {
    checkStatus();
  }, []);

  if (phase === "loading") {
    return (
      <div className="flex h-full w-full items-center justify-center">
        <div className="flex flex-col items-center gap-3 text-muted-foreground">
          <div className="flex h-12 w-12 animate-pulse items-center justify-center rounded-xl bg-primary text-primary-foreground">
            <Lock className="h-6 w-6" />
          </div>
          <span className="text-sm">Loading ROVault…</span>
        </div>
      </div>
    );
  }

  if (phase === "onboarding") {
    return <Onboarding onComplete={() => setPhase("unlocked")} />;
  }

  if (phase === "locked") {
    return (
      <LockScreen
        vaultName={vaultName}
        onUnlocked={() => setPhase("unlocked")}
      />
    );
  }

  return <Dashboard onLock={() => setPhase("locked")} />;
}
