184|/// Create a brand-new vault from a master password.
185|pub fn provision(password: &str, kdf: KdfParams) -> Result<Provisioned, CryptoError> {
186|    let dek = SecretKey::random()?;
187|
188|    // Recovery key: human-copyable Base32.
189|    let entropy = random_bytes(RECOVERY_ENTROPY_BYTES);
190|    let recovery_key = format_recovery_key(&entropy);
191|    let recovery_secret = normalize_recovery_key(&recovery_key);
192|
193|    let password_salt = random_bytes(SALT_LEN);
194|    let recovery_salt = random_bytes(SALT_LEN);
195|
196|    let password_kek = derive_kek(password.as_bytes(), &password_salt, &kdf)?;
197|    let recovery_kek = derive_kek(recovery_secret.as_bytes(), &recovery_salt, &kdf)?;
198|
199|    let wrapped_dek_password = seal(&password_kek, dek.as_bytes())?;
200|    let wrapped_dek_recovery = seal(&recovery_kek, dek.as_bytes())?;
201|    let verifier = seal(&dek, VERIFIER_PLAINTEXT)?;
202|
203|    Ok(Provisioned {
204|        keyfile: KeyFile {
