    let key = SecretKey::from_bytes(biometric_kek)?;
    let dek_bytes = open(&key, wrapped)?;
    let dek = SecretKey::from_bytes(&dek_bytes)?;
    verify_dek(&dek, kf)?;
    Ok(dek)
}

