/// Block on a WinRT IAsyncOperation without an async runtime, using a completion
/// handler that signals a channel.
#[cfg(target_os = "windows")]
fn block_on<T>(
    op: windows::Foundation::IAsyncOperation<T>,
) -> windows::core::Result<T>
where
    T: windows::core::RuntimeType + 'static,
{
    use std::sync::mpsc;
    use windows::Foundation::{AsyncOperationCompletedHandler, AsyncStatus};

    let (tx, rx) = mpsc::channel();
    let handler = AsyncOperationCompletedHandler::new(move |sender, _status| {
        let _ = tx.send(sender.as_ref().map(|s| s.GetResults()));
        Ok(())
    });
    op.SetCompleted(&handler)?;
    match rx.recv() {
        Ok(Some(result)) => result,
        _ => {
            // Fall back to polling status if the channel closed unexpectedly.
            loop {
                match op.Status()? {
                    AsyncStatus::Completed => return op.GetResults(),
                    AsyncStatus::Error | AsyncStatus::Canceled => return op.GetResults(),
                    _ => std::thread::sleep(std::time::Duration::from_millis(20)),
                }
            }
        }
    }
}

