{"content": "import { useEffect, useState } from "react";
import { api, type VaultSummary } from "@/lib/api";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { useToast } from "@/components/toast";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogDescription,
  DialogFooter,
} from "@/components/ui/dialog";
import {
  Lock,
  Plus,
  ChevronRight,
  Fingerprint,
  Eye,
  EyeOff,
  KeyRound,
  Trash2,
} from "lucide-react";

type Mode = "list" | "unlock";

export function VaultPicker({
  onOpened,
  onCreateNew,
}: {
  onOpened: () => void;
  onCreateNew: () => void;
}) {
  const toast = useToast();
  const [vaults, setVaults] = useState<VaultSummary[]>([]);
  const [loading, setLoading] = useState(true);
  const [mode, setMode] = useState<Mode>("list");
  const [selected, setSelected] = useState<VaultSummary | null>(null);

  // unlock form
  const [useRecovery, setUseRecovery] = useState(false);
  const [secret, setSecret] = useState("");
  const [show, setShow] = useState(false);
  const [busy, setBusy] = useState(false);

  // delete confirm
  const [deleteTarget, setDeleteTarget] = useState<VaultSummary | null>(null);
  const [deletePw, setDeletePw] = useState("");
  const [deleteBusy, setDeleteBusy] = useState(false);

  async function refresh() {
    setLoading(true);
    try {
      setVaults(await api.listVaults());
    } catch (e) {
      toast(String(e), "error");
    } finally {
      setLoading(false);
    }
  }

  useEffect(() => {
    refresh();
  }, []);

  function pick(v: VaultSummary) {
    setSelected(v);
    setSecret("");
    setUseRecovery(false);
    setShow(false);
    setMode("unlock");
  }

  async function submitUnlock(e: React.FormEvent) {
    e.preventDefault();
    if (!selected || !secret) return;
    setBusy(true);
    try {
      await api.unlock(selected.id, secret, useRecovery);
      setSecret("");
      onOpened();
    } catch {
      toast(useRecovery ? "Invalid recovery key" : "Incorrect master password", "error");
    } finally {
      setBusy(false);
    }
  }

  async function biometricUnlock() {
    if (!selected) return;
    setBusy(true);
    try {
      await api.unlockBiometric(selected.id);
      onOpened();
    } catch (e) {
      toast(String(e), "error");
    } finally {
      setBusy(false);
    }
  }

  async function confirmDelete() {
    if (!deleteTarget) return;
    setDeleteBusy(true);
    try {
      await api.deleteVault(deleteTarget.id, deletePw);
      toast(`Vault "${deleteTarget.name}" deleted`, "success");
      setDeleteTarget(null);
      setDeletePw("");
      await refresh();
    } catch (e) {
      toast(String(e), "error");
    } finally {
      setDeleteBusy(false);
    }
  }

  return (
    <div className="flex h-full w-full items-center justify-center bg-gradient-to-br from-background via-background to-accent/30 p-6">
      <div className="w-full max-w-md animate-fade-in">
        <div className="mb-8 flex flex-col items-center text-center">
          <div className="mb-4 flex h-16 w-16 items-center justify-center rounded-2xl bg-primary text-primary-foreground shadow-lg">
            <Lock className="h-8 w-8" />
          </div>
          <h1 className="text-2xl font-bold tracking-tight">ROVault</h1>
          <p className="text-sm text-muted-foreground">
            {mode === "list"
              ? "Choose a vault to open"
              : `Unlock ${selected?.name || "vault"}`}
          </p>
        </div>

        <div className="rounded-xl border bg-card p-6 shadow-sm">
          {mode === "list" && (
            <div className="space-y-3">
              {loading ? (
                <p className="py-6 text-center text-sm text-muted-foreground">
                  Loading…
                </p>
              ) : vaults.length === 0 ? (
                <p className="py-6 text-center text-sm text-muted-foreground">
                  No vaults yet. Create your first one.
                </p>
              ) : (
                <div className="space-y-2">
                  {vaults.map((v) => (
                    <div
                      key={v.id}
                      className="group flex items-center gap-3 rounded-lg border p-3 transition-colors hover:bg-accent"
                    >
                      <button
                        onClick={() => pick(v)}
                        className="flex flex-1 items-center gap-3 text-left"
                      >
                        <div className="flex h-10 w-10 items-center justify-center rounded-lg bg-primary/10 text-primary">
                          <Lock className="h-4 w-4" />
                        </div>
                        <div className="min-w-0 flex-1">
                          <div className="flex items-center gap-1.5 font-medium">
                            {v.name || "Untitled vault"}
                            {v.biometric_enabled && (
                              <Fingerprint className="h-3.5 w-3.5 text-primary" />
                            )}
                          </div>
                          <div className="text-xs text-muted-foreground">
                            Created{" "}
                            {new Date(v.created_at * 1000).toLocaleDateString()}
                          </div>
                        </div>
                        <ChevronRight className="h-4 w-4 text-muted-foreground" />
                      </button>
                      <button
                        onClick={() => {
                          setDeleteTarget(v);
                          setDeletePw("");
                        }}
                        className="rounded p-1.5 text-muted-foreground opacity-0 transition-opacity hover:bg-destructive/10 hover:text-destructive group-hover:opacity-100"
                        aria-label="Delete vault"
                      >
                        <Trash2 className="h-4 w-4" />
                      </button>
                    </div>
                  ))}
                </div>
              )}

              <Button className="w-full" onClick={onCreateNew}>
                <Plus className="h-4 w-4" /> Create new vault
              </Button>
            </div>
          )}

          {mode === "unlock" && selected && (
            <form onSubmit={submitUnlock} className="space-y-4">
              <div className="space-y-2">
                <Label htmlFor="secret">
                  {useRecovery ? "Recovery key" : "Master password"}
                </Label>
                <div className="relative">
                  <Input
                    id="secret"
                    type={useRecovery || show ? "text" : "password"}
                    value={secret}
                    onChange={(e) => setSecret(e.target.value)}
                    placeholder={useRecovery ? "XXXX-XXXX-XXXX-…" : "••••••••"}
                    autoFocus
                    className={useRecovery ? "font-mono" : ""}
                  />
                  {!useRecovery && (
                    <button
                      type="button"
                      onClick={() => setShow((s) => !s)}
                      className="absolute right-2 top-1/2 -translate-y-1/2 text-muted-foreground hover:text-foreground"
                      aria-label={show ? "Hide" : "Show"}
                    >
                      {show ? <EyeOff className="h-4 w-4" /> : <Eye className="h-4 w-4" />}
                    </button>
                  )}
                </div>
              </div>

              <Button type="submit" className="w-full" disabled={busy}>
                {busy ? "Unlocking…" : "Unlock"}
              </Button>

              {selected.biometric_enabled && (
                <Button
                  type="button"
                  variant="outline"
                  className="w-full"
                  onClick={biometricUnlock}
                  disabled={busy}
                >
                  <Fingerprint className="h-4 w-4" /> Unlock with Windows Hello
                </Button>
              )}

              <div className="flex items-center justify-between text-xs">
                <button
                  type="button"
                  onClick={() => {
                    setUseRecovery((r) => !r);
                    setSecret("");
                  }}
                  className="flex items-center gap-1.5 text-muted-foreground hover:text-foreground"
                >
                  <KeyRound className="h-3.5 w-3.5" />
                  {useRecovery
                    ? "Use master password"
                    : "Forgot password? Use recovery key"}
                </button>
                <button
                  type="button"
                  onClick={() => setMode("list")}
                  className="text-muted-foreground hover:text-foreground"
                >
                  ← All vaults
                </button>
              </div>
            </form>
          )}
        </div>
      </div>

      {/* Delete vault confirmation */}
      <Dialog open={!!deleteTarget} onOpenChange={(o) => !o && setDeleteTarget(null)}>
        <DialogContent>
          <DialogHeader>
            <DialogTitle className="text-destructive">Delete vault</DialogTitle>
            <DialogDescription>
              Permanently delete <strong>{deleteTarget?.name}</strong> and all its
              credentials. This cannot be undone. Enter its master password to
              confirm.
            </DialogDescription>
          </DialogHeader>
          <div className="grid gap-2">
            <Label htmlFor="delpw">Master password</Label>
            <Input
              id="delpw"
              type="password"
              value={deletePw}
              onChange={(e) => setDeletePw(e.target.value)}
              autoFocus
            />
          </div>
          <DialogFooter>
            <Button variant="outline" onClick={() => setDeleteTarget(null)}>
              Cancel
            </Button>
            <Button
              variant="destructive"
              onClick={confirmDelete}
              disabled={deleteBusy || !deletePw}
            >
              {deleteBusy ? "Deleting…" : "Delete vault"}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  );
}
