{"content": "import { useEffect, useState } from "react";
import { api } from "@/lib/api";
import { Onboarding } from "@/screens/Onboarding";
import { VaultPicker } from "@/screens/VaultPicker";
import { Dashboard } from "@/screens/Dashboard";
import { Lock } from "lucide-react";

type Phase = "loading" | "picker" | "onboarding" | "unlocked";

export default function App() {
  const [phase, setPhase] = useState<Phase>("loading");

  async function boot() {
    try {
      const s = await api.sessionInfo();
      if (s.unlocked) {
        setPhase("unlocked");
        return;
      }
      const vaults = await api.listVaults();
      // No vaults at all -> straight into onboarding. Otherwise pick a vault.
      setPhase(vaults.length === 0 ? "onboarding" : "picker");
    } catch {
      setPhase("onboarding");
    }
  }

  useEffect(() => {
    boot();
  }, []);

  if (phase === "loading") {
    return (
      <div className="flex h-full w-full items-center justify-center">
        <div className="flex flex-col items-center gap-3 text-muted-foreground">
          <div className="flex h-12 w-12 animate-pulse items-center justify-center rounded-xl bg-primary text-primary-foreground">
            <Lock className="h-6 w-6" />
          </div>
          <span className="text-sm">Loading ROVault…</span>
        </div>
      </div>
    );
  }

  if (phase === "onboarding") {
    return (
      <Onboarding
        onComplete={() => setPhase("unlocked")}
        onCancel={() => setPhase("picker")}
      />
    );
  }

  if (phase === "picker") {
    return (
      <VaultPicker
        onOpened={() => setPhase("unlocked")}
        onCreateNew={() => setPhase("onboarding")}
      />
    );
  }

  return <Dashboard onLock={() => boot()} />;
}
