{"content": "import { useEffect, useState, useCallback } from "react";
import { writeText } from "@tauri-apps/plugin-clipboard-manager";
import { generatePassword, passwordStrength } from "@/lib/password";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Switch } from "@/components/ui/switch";
import { useToast } from "@/components/toast";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogDescription,
} from "@/components/ui/dialog";
import { RefreshCw, Copy, Check } from "lucide-react";
import { cn } from "@/lib/utils";

/**
 * A standalone generator you open from the dashboard to mint a password when
 * creating a new account elsewhere — copy it, use it, then save it as a
 * credential.
 */
export function PasswordGenerator({
  open,
  onClose,
}: {
  open: boolean;
  onClose: () => void;
}) {
  const toast = useToast();
  const [length, setLength] = useState(20);
  const [upper, setUpper] = useState(true);
  const [lower, setLower] = useState(true);
  const [numbers, setNumbers] = useState(true);
  const [symbols, setSymbols] = useState(true);
  const [value, setValue] = useState("");
  const [copied, setCopied] = useState(false);

  const regen = useCallback(() => {
    setValue(generatePassword(length, { upper, lower, numbers, symbols }));
    setCopied(false);
  }, [length, upper, lower, numbers, symbols]);

  useEffect(() => {
    if (open) regen();
  }, [open, regen]);

  const strength = passwordStrength(value);

  async function copy() {
    if (!value) return;
    await writeText(value);
    setCopied(true);
    toast("Password copied — paste it into your new account", "success");
    setTimeout(async () => {
      try {
        await writeText("");
      } catch {
        /* ignore */
      }
    }, 20000);
  }

  return (
    <Dialog open={open} onOpenChange={(o) => !o && onClose()}>
      <DialogContent>
        <DialogHeader>
          <DialogTitle>Password generator</DialogTitle>
          <DialogDescription>
            Generate a strong password, copy it, and use it when creating a new
            account. Then save it here as a credential.
          </DialogDescription>
        </DialogHeader>

        <div className="space-y-4">
          <div className="flex items-center gap-2 rounded-lg border bg-muted/40 p-3">
            <code className="flex-1 break-all font-mono text-sm">{value}</code>
            <Button variant="ghost" size="icon" onClick={regen} title="Regenerate">
              <RefreshCw className="h-4 w-4" />
            </Button>
            <Button variant="ghost" size="icon" onClick={copy} title="Copy">
              {copied ? (
                <Check className="h-4 w-4 text-green-500" />
              ) : (
                <Copy className="h-4 w-4" />
              )}
            </Button>
          </div>

          <div className="flex items-center gap-2">
            <div className="flex h-1.5 flex-1 gap-1">
              {[0, 1, 2, 3].map((i) => (
                <div
                  key={i}
                  className={cn(
                    "h-full flex-1 rounded-full bg-muted",
                    i < strength.score &&
                      (strength.score <= 1
                        ? "bg-destructive"
                        : strength.score <= 2
                        ? "bg-yellow-500"
                        : "bg-green-500")
                  )}
                />
              ))}
            </div>
            <span className="text-xs text-muted-foreground">{strength.label}</span>
          </div>

          <div className="space-y-2">
            <div className="flex items-center justify-between">
              <Label>Length</Label>
              <span className="text-sm text-muted-foreground">{length}</span>
            </div>
            <input
              type="range"
              min={8}
              max={64}
              value={length}
              onChange={(e) => setLength(Number(e.target.value))}
              className="w-full accent-[hsl(var(--primary))]"
            />
          </div>

          <div className="grid grid-cols-2 gap-3">
            <Toggle label="Uppercase (A-Z)" checked={upper} onChange={setUpper} />
            <Toggle label="Lowercase (a-z)" checked={lower} onChange={setLower} />
            <Toggle label="Numbers (0-9)" checked={numbers} onChange={setNumbers} />
            <Toggle label="Symbols (!@#)" checked={symbols} onChange={setSymbols} />
          </div>

          <Button className="w-full" onClick={copy}>
            <Copy className="h-4 w-4" /> Copy password
          </Button>
        </div>
      </DialogContent>
    </Dialog>
  );
}

function Toggle({
  label,
  checked,
  onChange,
}: {
  label: string;
  checked: boolean;
  onChange: (v: boolean) => void;
}) {
  return (
    <label className="flex items-center justify-between gap-2 rounded-md border p-2.5 text-sm">
      <span className="text-muted-foreground">{label}</span>
      <Switch checked={checked} onCheckedChange={onChange} />
    </label>
  );
}

