{"content": "import { useEffect, useState, useRef } from "react";
import { api } from "@/lib/api";
import { writeText } from "@tauri-apps/plugin-clipboard-manager";
import { Copy, ShieldCheck } from "lucide-react";
import { useToast } from "@/components/toast";

/** Live TOTP 6-digit code with countdown ring, refreshing every second. */
export function TotpDisplay({ secret }: { secret: string }) {
  const toast = useToast();
  const [code, setCode] = useState("------");
  const [remaining, setRemaining] = useState(30);
  const [valid, setValid] = useState(true);
  const timer = useRef<ReturnType<typeof setInterval>>();

  useEffect(() => {
    let cancelled = false;
    async function tick() {
      try {
        const r = await api.totpCode(secret);
        if (!cancelled) {
          setCode(r.code);
          setRemaining(r.seconds_remaining);
          setValid(true);
        }
      } catch {
        if (!cancelled) setValid(false);
      }
    }
    tick();
    timer.current = setInterval(tick, 1000);
    return () => {
      cancelled = true;
      if (timer.current) clearInterval(timer.current);
    };
  }, [secret]);

  if (!valid) {
    return (
      <div className="flex items-center gap-2 rounded-md bg-muted/50 px-2.5 py-1.5 text-xs text-muted-foreground">
        <ShieldCheck className="h-3.5 w-3.5" /> Invalid 2FA secret
      </div>
    );
  }

  const pct = (remaining / 30) * 100;

  return (
    <div className="flex items-center gap-2 rounded-md bg-muted/50 px-2.5 py-1.5">
      <ShieldCheck className="h-3.5 w-3.5 shrink-0 text-primary" />
      <div className="min-w-0 flex-1">
        <div className="text-[10px] uppercase tracking-wide text-muted-foreground">
          2FA code
        </div>
        <div className="font-mono text-sm tracking-widest">
          {code.slice(0, 3)} {code.slice(3)}
        </div>
      </div>
      <div
        className="relative h-6 w-6 shrink-0"
        title={`${remaining}s remaining`}
        aria-label={`${remaining} seconds remaining`}
      >
        <svg viewBox="0 0 36 36" className="h-6 w-6 -rotate-90">
          <circle
            cx="18"
            cy="18"
            r="15"
            fill="none"
            stroke="hsl(var(--border))"
            strokeWidth="3"
          />
          <circle
            cx="18"
            cy="18"
            r="15"
            fill="none"
            stroke="hsl(var(--primary))"
            strokeWidth="3"
            strokeDasharray={`${(pct / 100) * 94.2} 94.2`}
          />
        </svg>
        <span className="absolute inset-0 flex items-center justify-center text-[9px] font-medium">
          {remaining}
        </span>
      </div>
      <button
        onClick={async () => {
          await writeText(code);
          toast("2FA code copied", "success");
        }}
        className="text-muted-foreground hover:text-foreground"
        aria-label="Copy 2FA code"
      >
        <Copy className="h-3.5 w-3.5" />
      </button>
    </div>
  );
}
