{"mode":"replace","new_string":"pub fn default_kdf() -> KdfParams {
    KdfParams::default()
}

/// Parse an encrypted `.rovault` backup and prepare it as a new local vault.
/// The encrypted entries and wrapped keys are preserved byte-for-byte; only
/// local identity metadata changes so importing cannot overwrite an existing vault.
pub fn prepare_encrypted_import(
    json: &str,
    new_id: &str,
    imported_at: i64,
) -> Result<VaultFile, StoreError> {
    let mut vault: VaultFile =
        serde_json::from_str(json).map_err(|e| StoreError::Serde(e.to_string()))?;
    if vault.version != 1
        || vault.keyfile.wrapped_dek_password.is_empty()
        || vault.keyfile.wrapped_dek_recovery.is_empty()
        || vault.keyfile.verifier.is_empty()
        || vault.entries_blob.is_empty()
    {
        return Err(StoreError::Serde("invalid or unsupported encrypted ROVault backup".into()));
    }
    vault.id = new_id.to_string();
    vault.name = format!("{} (Imported)", vault.name.trim());
    vault.created_at = imported_at;
    Ok(vault)
}

